BEGIN;

-- Rehace editorial_entity_references de los documentos cuyas filas no coincidían con sus artistReference (una edición anterior solo miraba los párrafos de primer nivel y borró las referencias dentro de listas).

DELETE FROM editorial_entity_references WHERE editorial_document_id = (SELECT d.id FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id WHERE a.slug = 'hector-acosta-el-torito' AND d.locale = 'es' AND d.document_type = 'artist_biography');

DELETE FROM editorial_entity_references WHERE editorial_document_id = (SELECT d.id FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id WHERE a.slug = 'hector-acosta-el-torito' AND d.locale = 'en' AND d.document_type = 'artist_biography');

DELETE FROM editorial_entity_references WHERE editorial_document_id = (SELECT d.id FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id WHERE a.slug = 'romeo-santos' AND d.locale = 'en' AND d.document_type = 'artist_biography');

DELETE FROM editorial_entity_references WHERE editorial_document_id = (SELECT d.id FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id WHERE a.slug = 'romeo-santos' AND d.locale = 'es' AND d.document_type = 'artist_biography');

DELETE FROM editorial_entity_references WHERE editorial_document_id = (SELECT d.id FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id WHERE a.slug = 'aventura' AND d.locale = 'es' AND d.document_type = 'artist_biography');

DELETE FROM editorial_entity_references WHERE editorial_document_id = (SELECT d.id FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id WHERE a.slug = 'aventura' AND d.locale = 'en' AND d.document_type = 'artist_biography');

COMMIT;
